#!/usr/bin/env python3
"""Concept evaluation report: docs/CONCEPTS_EVALUATION.md and a rendered view of the concept meshes (concepts/out/concepts_view.png). GENERATED."""
import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(HERE, "out"); ROOT = os.path.dirname(HERE)
def main():
    h = json.load(open(os.path.join(OUT, "head_concept.json"))); s = json.load(open(os.path.join(OUT, "shaft_concept.json")))
    L = ["# Owner concept boards: isolated evaluation (generated by concepts/report.py; MODELED)", "",
         "Tested in isolation from the AXE2 design: AXE2 rules do not constrain this study; AXE2 values appear only as a reference. Physics library concepts/clib.py "
         f"(magpylib field, Neumann inductance), self-checked: {h['selftest']}. Real part data from datasheets on file (DATASHEET_LOG RF2-DS-CONCEPTS); ASSUMED values are named in each script.", "",
         "## Search head (Hyperion REV 03 / 05 / 06)", ""] + [f"- {f}" for f in h["findings"]] + ["",
         "### TX coil sweep (50 A, concept switch BSC007N04LS6: 40 V, Coss 2.1 nF, 36 V clamp)", "", "| Coil | Turns | L uH | B at 200 mm per A uT | B200 per sqrt(J) uT | Winding C pF | Fall us | First sample us | Pulse mJ |", "|---|---|---|---|---|---|---|---|---|"]
    for r in h["tx_sweep_concept_switch"]: L.append(f"| {r['kind']} | {r['turns']} | {r['L_uH']} | {r['B_uT_per_A']['200 mm']} | {r['B200_per_sqrtJ_uT']} | {r['C_self_pF']} | {r['fall_us']:.1f} | {r['first_sample_us']:.1f} | {r['E_pulse_mJ']} |")
    L += ["", "### 'Zero capacitance' honeycomb, 8-turn hex at 50 A", "", "| Winding | Switch | L uH | Winding C pF | Node C pF | First sample us |", "|---|---|---|---|---|---|"]
    for c in h["capacitance_cases_8turn_hex_50A"]: L.append(f"| {c['case']} | {c['switch']} | {c['L_uH']} | {c['C_self_pF']} | {c['C_node_pF']} | {c['first_sample_us']:.1f} |")
    L += ["", f"Reference AXE2: {h['reference_AXE2']}. Concept head mass estimate: {h['mass']}", "",
          "## Shafts (Axis REV A / REV 04 / REV 05)", ""] + [f"- {f}" for f in s["findings"]] + ["", f"Reference: {s['reference']}", "",
          "## What survives the isolated test", "",
          "- A low-inductance TX (about 8 turns, 30 uH) driven hard by a 900 V-class SiC switch reads at about 4-5 us with the same field per joule as a 26-turn coil: the concept's direction is sound, its named 40 V switch is not.",
          "- A planar RX on polyimide is quiet (0.87 nV/rtHz for 20 turns) but must be geometrically nulled (bucking / DD / quadrupole).",
          "- An optical data link up the shaft (1 mm POF) is a real EMI gain.",
          "- Rejected by the physics: Mu-metal fins or conduit near the coil (ferrous targets), 0.1 mm shell, ADS1282 for PI sampling, a single WS2812 chain for 360 LEDs inside the PI period, 'metamaterial' core, EM waveguide, three RG316-DS in a 3 mm conduit, a 6-layer accordion fold.", "",
          "## Files", "", "STL parts and STEP assemblies in concepts/out/ (head_*.stl, head_concept.step, shaft_*.stl, shaft_A_concept.step, shaft_B_concept.step); view: concepts/out/concepts_view.png."]
    open(os.path.join(ROOT, "docs", "CONCEPTS_EVALUATION.md"), "w").write("\n".join(L) + "\n")
    try:
        import pyvista as pv
        pv.OFF_SCREEN = True; pl = pv.Plotter(off_screen=True, shape=(1, 2), window_size=(1800, 800))
        cols = dict(SHELL="#888888", LATTICE_BAND="#bb9966", TX_HEX_8T="#d07a20", RX_NESTED_HEX="#20a060", FINS_MUMETAL_RADIAL="#4060c0", RING_GRAPHENE_CONCENTRIC="#202020",
                    LED_BOARD="#205020", LEDS_360_3535="#f0f0a0", SOC_MODULE_ADS1282_IGLOO2_4xBSC007="#2a6a2a", RG316DS_EXIT="#c04040", RX_POLYIMIDE="#c8a040")
        pl.subplot(0, 0)
        for k, c in cols.items():
            f = os.path.join(OUT, f"head_{k}.stl")
            if os.path.exists(f): pl.add_mesh(pv.read(f), color=c, opacity=0.35 if k in ("SHELL", "LED_BOARD", "RX_POLYIMIDE") else 1.0)
        pl.add_text("Hyperion head concept (229 mm)", font_size=12); pl.view_isometric()
        pl.subplot(0, 1); x = 0
        for k, c in (("A_SHELL_CF", "#555555"), ("A_CONDUIT_MUMETAL", "#4060c0"), ("A_FINS_PEEK", "#bb9966"), ("A_CABLES_RG316DS", "#c04040"), ("A_RIGIDFLEX_ACCORDION", "#20a060"),
                     ("B_SHELL_PEEK_0p1", "#aaaaaa"), ("B_FLEX_HELICAL", "#20a060"), ("B_CORE_GRID", "#8040a0"), ("B_WAVEGUIDE_TUBE", "#cccccc"), ("B_TWINAX", "#c04040")):
            f = os.path.join(OUT, f"shaft_{k}.stl")
            if os.path.exists(f): m = pv.read(f); m.translate((0 if k.startswith("A_") else 40, 0, 0), inplace=True); pl.add_mesh(m, color=c, opacity=0.3 if "SHELL" in k else 1.0)
        pl.add_text("Shaft B helical (left) / A finned hex-bore (right), 300 mm sections", font_size=12); pl.view_isometric()
        pl.screenshot(os.path.join(OUT, "concepts_view.png")); pl.close()
    except Exception as ex: print("render skipped:", ex)
    print("report written"); return True
if __name__ == "__main__": main()
